import uuid, json, pathlib
from typing import List
from dataclasses import dataclass, field

COMMENT_PREFIX = {
    'python': '#', 'cpp': '//', 'csharp': '//',
    'js': '//', 'ts': '//', 'rust': '//', 'go': '//'
}

@dataclass
class AtomicUnit:
    uuid: str
    integration_group: str
    expansion_ports: List[str]
    cross_refs: List[str]
    lang: str
    layer: str
    code: str
    file_path: str = ''

class AtomicReferenceSystem:
    REGISTRY_PATH = pathlib.Path('memory_fabric/indices/atomic_registry.json')

    def __init__(self):
        self.registry: dict[str, AtomicUnit] = self._load()
        self.groups: dict[str, List[str]] = {}
        for uid, unit in self.registry.items():
            self.groups.setdefault(unit.integration_group, []).append(uid)

    def _load(self) -> dict:
        if not self.REGISTRY_PATH.exists():
            return {}
        raw = json.loads(self.REGISTRY_PATH.read_text())
        return {k: AtomicUnit(**v) for k, v in raw.items()}

    def _save(self):
        self.REGISTRY_PATH.parent.mkdir(parents=True, exist_ok=True)
        self.REGISTRY_PATH.write_text(
            json.dumps({k: vars(v) for k, v in self.registry.items()}, indent=2)
        )

    def stamp(
        self,
        code: str,
        integration_group: str,
        expansion_ports: List[str],
        cross_refs: List[str],
        lang: str = 'python',
        layer: str = 'logic'
    ) -> AtomicUnit:
        uid = uuid.uuid4().hex[:12]
        prefix = COMMENT_PREFIX.get(lang, '#')
        header = (
            f'{prefix} ATOMIC_REF::uuid={uid}\n'
            f'{prefix} INTEGRATION_GROUP::{integration_group}\n'
            f'{prefix} EXPANSION_PORTS::{",".join(expansion_ports) or "none"}\n'
            f'{prefix} CROSS_REFS::{",".join(cross_refs) or "none"}\n'
            f'{prefix} LAYER::{layer}\n'
        )
        unit = AtomicUnit(
            uuid=uid,
            integration_group=integration_group,
            expansion_ports=expansion_ports,
            cross_refs=cross_refs,
            lang=lang,
            layer=layer,
            code=header + code
        )
        self.registry[uid] = unit
        self.groups.setdefault(integration_group, []).append(uid)
        self._save()
        return unit

    def pull_group_to_context(self, integration_group: str) -> str:
        uids = self.groups.get(integration_group, [])
        return '\n\n'.join(
            self.registry[uid].code for uid in uids if uid in self.registry
        )

    def batch_replace(self, integration_group: str, find: str, replace: str) -> int:
        uids = self.groups.get(integration_group, [])
        count = 0
        for uid in uids:
            if uid in self.registry:
                unit = self.registry[uid]
                if find in unit.code:
                    unit.code = unit.code.replace(find, replace)
                    count += 1
        self._save()
        return count

from memory_index_manager import TokenAwareIndex
from atomic_reference_system import AtomicReferenceSystem

TOKENS_PER_CHAR = 0.25
MAX_TOKENS = 512
SYSTEM_OVERHEAD = 80

class ContextAssembler:
    def __init__(self, domain: str):
        self.domain = domain
        self.index = TokenAwareIndex(context_limit=MAX_TOKENS)
        self.ars = AtomicReferenceSystem()

    def _tok(self, text: str) -> int:
        return max(1, int(len(text) * TOKENS_PER_CHAR))

    def build(self, user_prompt: str, active_groups: list[str] = None) -> str:
        budget = MAX_TOKENS - SYSTEM_OVERHEAD - self._tok(user_prompt)
        parts = []

        memories = self.index.get_relevant_memories(user_prompt)
        for mem in memories:
            preview = f'[MEM:{mem.id}] {mem.content_preview}'
            cost = self._tok(preview)
            if budget - cost >= 0:
                parts.append(preview)
                budget -= cost

        if active_groups:
            for group in active_groups:
                group_code = self.ars.pull_group_to_context(group)
                cost = self._tok(group_code)
                if budget - cost >= 0:
                    parts.append(f'[GROUP:{group}]\n{group_code}')
                    budget -= cost

        context = '\n'.join(parts)
        return f'<memory>\n{context}\n</memory>\n\nUser: {user_prompt}'

