import json, pathlib, uuid, time

SCHEMA_PATH = 'memory_fabric/automation/schema_templates/game_schema_filled.json'
OUTPUT_PATH = pathlib.Path('projects/rpg_game')

def stamp(code: str, group: str, ports: list, lang: str = 'cpp') -> str:
    uid = uuid.uuid4().hex[:12]
    pfx = '//'
    return (
        f'{pfx} ATOMIC_REF::uuid={uid}\n'
        f'{pfx} INTEGRATION_GROUP::{group}\n'
        f'{pfx} EXPANSION_PORTS::{",".join(ports)}\n'
        f'{pfx} LAYER::logic\n' + code
    )

def generate_npc_system(schema: dict) -> str:
    npc_types = schema.get('npc_systems', ['warrior', 'merchant', 'guard'])
    blocks = []
    for npc in npc_types:
        code = f"""
struct {npc.capitalize()}State {{
    float health;
    float aggression;
    std::string current_action;
}};

std::string {npc}_decide_action(const {npc.capitalize()}State& state) {{
    // EXPAND_NEXT: Add behavior tree logic here
    if (state.aggression > 0.7f) return "attack";
    return "patrol";
}}
"""
        blocks.append(stamp(code, 'npc_behavior_system', ['behavior_tree', 'dialogue'], 'cpp'))
    return '\n'.join(blocks)

def generate_inventory_system(schema: dict) -> str:
    code = """
struct Item { std::string id; std::string name; int quantity; float weight; };
struct Inventory { std::vector<Item> items; float max_weight; };
bool add_item(Inventory& inv, const Item& item) {
    // EXPAND_NEXT: add weight check, stack logic, event hooks
    inv.items.push_back(item);
    return true;
}
"""
    return stamp(code, 'inventory_system', ['weight_system', 'events'], 'cpp')

def generate_combat_system(schema: dict) -> str:
    code = """
struct CombatResult { float damage_dealt; bool is_critical; std::string outcome; };
CombatResult resolve_combat(float attacker_str, float defender_def) {
    // EXPAND_NEXT: add status effects, crit multipliers, animation hooks
    float dmg = std::max(0.0f, attacker_str - defender_def * 0.5f);
    return {dmg, false, dmg > 0 ? "hit" : "miss"};
}
"""
    return stamp(code, 'combat_system', ['status_effects', 'animations'], 'cpp')

if __name__ == '__main__':
    schema = json.loads(pathlib.Path(SCHEMA_PATH).read_text())
    OUTPUT_PATH.mkdir(parents=True, exist_ok=True)

    files = {
        'src/npc/npc_system.cpp':       generate_npc_system(schema),
        'src/inventory/inventory.cpp':  generate_inventory_system(schema),
        'src/combat/combat.cpp':        generate_combat_system(schema),
    }

    manifest = {}
    for rel_path, content in files.items():
        full_path = OUTPUT_PATH / rel_path
        full_path.parent.mkdir(parents=True, exist_ok=True)
        full_path.write_text(content)
        manifest[rel_path] = {'size': len(content), 'ts': time.time()}
        print(f'Generated: {rel_path} ({len(content)} chars)')

    (OUTPUT_PATH / 'manifest.json').write_text(json.dumps(manifest, indent=2))
    print(f'Build complete. {len(files)} files generated.')

import subprocess, json, pathlib, time

class ScriptExecutor:
    def run(self, script_path: str, timeout: int = 120) -> dict:
        start = time.time()
        try:
            result = subprocess.run(
                ['python', script_path],
                capture_output=True, text=True, timeout=timeout
            )
            return {
                'success': result.returncode == 0,
                'stdout': result.stdout[-2000:],
                'stderr': result.stderr[-500:],
                'duration_s': round(time.time() - start, 2)
            }
        except subprocess.TimeoutExpired:
            return {'success': False, 'stdout': '', 'stderr': 'Timeout', 'duration_s': timeout}

class ResultCompressor:
    TOKENS_PER_CHAR = 0.25

    def compress(self, project_path: str, exec_result: dict, max_tokens: int = 80) -> str:
        manifest_path = pathlib.Path(project_path) / 'manifest.json'
        if manifest_path.exists():
            manifest = json.loads(manifest_path.read_text())
            file_count = len(manifest)
            total_chars = sum(v.get('size', 0) for v in manifest.values())
        else:
            file_count, total_chars = 0, 0

        expansion_points = self._scan_expansion_ports(project_path)

        lines = [
            f"BUILD: {'OK' if exec_result['success'] else 'FAILED'}",
            f'Files: {file_count} | Total: {total_chars} chars',
            f"Next ports: {', '.join(expansion_points[:5])}",
        ]
        if not exec_result['success']:
            lines.append(f"Error: {exec_result['stderr'][:100]}")
        return '\n'.join(lines)

    def _scan_expansion_ports(self, project_path: str) -> list:
        ports = []
        for ext in ('*.cpp', '*.py', '*.cs', '*.js', '*.ts'):
            for f in pathlib.Path(project_path).rglob(ext):
                for line in f.read_text(errors='ignore').splitlines():
                    if 'EXPANSION_PORTS::' in line:
                        raw = line.split('EXPANSION_PORTS::')[1]
                        ports.extend(p.strip() for p in raw.split(',') if p.strip() != 'none')
        return list(dict.fromkeys(ports))

