class ExpansionRunner:
    def __init__(self, controller: MetaAgentController, project_path: str):
        self.ctrl = controller
        self.project_path = pathlib.Path(project_path)
        self.ars = AtomicReferenceSystem()

    def get_pending_ports(self) -> list[tuple[str, str]]:
        pending = []
        for ext in ('*.cpp', '*.py', '*.cs', '*.js', '*.ts'):
            for f in self.project_path.rglob(ext):
                group = None
                for line in f.read_text(errors='ignore').splitlines():
                    if 'INTEGRATION_GROUP::' in line:
                        group = line.split('INTEGRATION_GROUP::')[1].strip()
                    if 'EXPANSION_PORTS::' in line and group:
                        ports_raw = line.split('EXPANSION_PORTS::')[1]
                        for port in ports_raw.split(','):
                            port = port.strip()
                            if port and port != 'none':
                                pending.append((group, port))
        return list(dict.fromkeys(pending))

    def run_one_expansion(self) -> str:
        pending = self.get_pending_ports()
        if not pending:
            return 'No expansion ports remaining. Codebase is fully expanded.'

        group_id, port_name = pending[0]
        group_code = self.ars.pull_group_to_context(group_id)

        prompt = (
            f"Expand the '{port_name}' expansion port in the '{group_id}' integration group.\n"
            f'Write a Python automation script that generates the implementation.\n'
            f'Reference code:\n{group_code[:300]}'
        )
        return self.ctrl.handle_turn(prompt, active_groups=[group_id])

    def run_all(self, max_cycles: int = 20) -> list[str]:
        results = []
        for i in range(max_cycles):
            result = self.run_one_expansion()
            results.append(result)
            if 'No expansion ports' in result:
                break
        return results

import json, time, pathlib, shutil

class DriveRouter:
    def __init__(self, hot_base: str, warm_base: str, cold_base: str):
        self.tiers = {
            'hot':  (pathlib.Path(hot_base),  7  * 86400),
            'warm': (pathlib.Path(warm_base), 30 * 86400),
            'cold': (pathlib.Path(cold_base), float('inf')),
        }

    def resolve(self, file_path: str) -> pathlib.Path:
        rel = pathlib.Path(file_path).name
        for tier, (base, _) in self.tiers.items():
            candidate = base / rel
            if candidate.exists():
                return candidate
        return pathlib.Path(file_path)

    def promote_or_demote(self, file_path: str, last_access_ts: float):
        age = time.time() - last_access_ts
        src = self.resolve(file_path)
        if not src.exists():
            return

        if age < self.tiers['hot'][1]:
            target_base = self.tiers['hot'][0]
        elif age < self.tiers['warm'][1]:
            target_base = self.tiers['warm'][0]
        else:
            target_base = self.tiers['cold'][0]

        dest = target_base / src.name
        if src != dest:
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(src), str(dest))

    def migrate_all(self, index_records: list):
        for rec in index_records:
            self.promote_or_demote(rec['file_path'], rec['timestamp'])

from abc import ABC, abstractmethod
import json, urllib.request

class LLMAdapter(ABC):
    @abstractmethod
    def call(self, prompt: str, max_tokens: int = 512) -> str: ...

class LocalOllamaAdapter(LLMAdapter):
    def __init__(self, model: str = 'mistral', host: str = 'http://localhost:11434'):
        self.model = model
        self.host = host

    def call(self, prompt: str, max_tokens: int = 512) -> str:
        payload = json.dumps({
            'model': self.model,
            'prompt': prompt,
            'stream': False,
            'options': {'num_predict': max_tokens}
        }).encode()
        req = urllib.request.Request(
            f'{self.host}/api/generate',
            data=payload,
            headers={'Content-Type': 'application/json'}
        )
        with urllib.request.urlopen(req, timeout=60) as r:
            return json.loads(r.read())['response']

class AnthropicAdapter(LLMAdapter):
    def __init__(self, api_key: str, model: str = 'claude-haiku-4-5-20251001'):
        self.api_key = api_key
        self.model = model

    def call(self, prompt: str, max_tokens: int = 512) -> str:
        payload = json.dumps({
            'model': self.model,
            'max_tokens': max_tokens,
            'messages': [{'role': 'user', 'content': prompt}]
        }).encode()
        req = urllib.request.Request(
            'https://api.anthropic.com/v1/messages',
            data=payload,
            headers={
                'Content-Type': 'application/json',
                'x-api-key': self.api_key,
                'anthropic-version': '2023-06-01'
            }
        )
        with urllib.request.urlopen(req, timeout=60) as r:
            data = json.loads(r.read())
        return data['content'][0]['text']

class OpenAIAdapter(LLMAdapter):
    def __init__(self, api_key: str, model: str = 'gpt-4o-mini'):
        self.api_key = api_key
        self.model = model

    def call(self, prompt: str, max_tokens: int = 512) -> str:
        payload = json.dumps({
            'model': self.model,
            'max_tokens': max_tokens,
            'messages': [{'role': 'user', 'content': prompt}]
        }).encode()
        req = urllib.request.Request(
            'https://api.openai.com/v1/chat/completions',
            data=payload,
            headers={
                'Content-Type': 'application/json',
                'Authorization': f'Bearer {self.api_key}'
            }
        )
        with urllib.request.urlopen(req, timeout=60) as r:
            data = json.loads(r.read())
        return data['choices'][0]['message']['content']

import argparse, sys
from llm_adapter import LocalOllamaAdapter, AnthropicAdapter, OpenAIAdapter
from meta_agent_controller import MetaAgentController
from expansion_runner import ExpansionRunner

def build_controller(model: str, api_key: str = None, domain: str = 'default') -> MetaAgentController:
    if model.startswith('claude'):
        adapter = AnthropicAdapter(api_key=api_key, model=model)
    elif model.startswith('gpt'):
        adapter = OpenAIAdapter(api_key=api_key, model=model)
    else:
        adapter = LocalOllamaAdapter(model=model)
    return MetaAgentController(domain=domain, llm_caller=adapter.call)

def main():
    parser = argparse.ArgumentParser(description='Agent meta-architecture CLI')
    parser.add_argument('--model',      default='mistral',  help='Model name (mistral, claude-*, gpt-*)')
    parser.add_argument('--domain',     default='default',  help='Project domain name')
    parser.add_argument('--api-key',    default=None,       help='API key for cloud models')
    parser.add_argument('--message',    default=None,       help='Single message and exit')
    parser.add_argument('--expand',     default=None,       help='Project path to run expansion cycles on')
    parser.add_argument('--max-cycles', type=int, default=10, help='Max expansion cycles (default 10)')
    args = parser.parse_args()

    ctrl = build_controller(args.model, args.api_key, args.domain)

    if args.expand:
        runner = ExpansionRunner(ctrl, args.expand)
        results = runner.run_all(max_cycles=args.max_cycles)
        for r in results:
            print(r)
        return

    if args.message:
        print(ctrl.handle_turn(args.message))
        return

    print('Agent ready. Type your message. Ctrl-C to exit.')
    while True:
        try:
            user_input = input('You: ').strip()
            if not user_input:
                continue
            response = ctrl.handle_turn(user_input)
            print(f'Agent: {response}\n')
        except KeyboardInterrupt:
            print('\nExiting.')
            sys.exit(0)

if __name__ == '__main__':
    main()
